raw_text:
{
  "verifications": [
    {
      "fact_id": "COFFEE-001",
      "verdict": "VERIFIED",
      "verification_notes": "ICOの2026年9月報告で、I-CIP平均262.18米セント／ポンド、前月比8.7%下落、ブラジルの供給増・潤沢な供給見通しによる下押し、認証済みアラビカ在庫の少なさ・エルニーニョ不確実性による下支えが確認できます。([ico.org](https://www.ico.org/documents/cy2025-26/cmr-0926-e.pdf))"
    },
    {
      "fact_id": "COFFEE-002",
      "verdict": "VERIFIED",
      "verification_notes": "ICO報告の各グループ価格と前月比は記載どおりです。3つのアラビカ系グループとロブスタを区別している点も適切です。([ico.org](https://www.ico.org/documents/cy2025-26/cmr-0926-e.pdf))"
    },
    {
      "fact_id": "COFFEE-003",
      "verdict": "VERIFIED",
      "verification_notes": "Reuters記事は2025年1月29日のICEアラビカ先物について、一時369.45米セント／ポンド、終値366.55米セント／ポンドと報じています。記載を「当時の過去最高値」と限定している点も妥当です。([investing.com](https://www.investing.com/news/commodities-news/coffee-prices-surge-to-record-highs-above-360-per-lb-3837609))"
    },
    {
      "fact_id": "COFFEE-004",
      "verdict": "AMBIGUOUS",
      "verification_notes": "70～80%は記事前半にディーラーの説明としてありますが、同じ記事の後半ではブラジルの当該収穫の約80～90%が販売済みとも記載され、数字が一致しません。Conabの次期作4.4%減という予測は確認できますが、販売済み割合は一つの確定値として扱わないのが適切です。([investing.com](https://www.investing.com/news/commodities-news/coffee-prices-surge-to-record-highs-above-360-per-lb-3837609))"
    },
    {
      "fact_id": "COFFEE-005",
      "verdict": "VERIFIED",
      "verification_notes": "USDAの2026年7月報告は、ブラジルのアラビカ生産低迷、エチオピア・メキシコ・ペルーの増産だけでは損失を補えなかったこと、世界の期末在庫が2020/21～2024/25年度に1,550万袋減ったことを記載しています。([apps.fas.usda.gov](https://apps.fas.usda.gov/psdonline/circulars/2026/07/coffee.pdf))"
    },
    {
      "fact_id": "COFFEE-006",
      "verdict": "VERIFIED",
      "verification_notes": "USDAは年度ごとに干ばつ・高温・霜・降雨不足や過剰な降雨などを説明し、2024/25年度と2025/26年度には干ばつと暑さが生産を低下させたとしています。単一の天候要因にまとめていない点も適切です。([apps.fas.usda.gov](https://apps.fas.usda.gov/psdonline/circulars/2026/07/coffee.pdf))"
    },
    {
      "fact_id": "COFFEE-007",
      "verdict": "VERIFIED",
      "verification_notes": "USDAの2026年7月報告はブラジル2026/27年度の総生産を7,190万袋、アラビカを4,750万袋、アラビカの前年比増を950万袋と予測し、開花期の適時の降雨とミナスジェライス州の良好な果実発育にも言及しています。予測としての扱いも適切です。([apps.fas.usda.gov](https://apps.fas.usda.gov/psdonline/circulars/2026/07/coffee.pdf))"
    },
    {
      "fact_id": "COFFEE-008",
      "verdict": "VERIFIED",
      "verification_notes": "USDAの2026年7月報告にある2026/27年度の世界生産1億8,970万袋、消費1億7,970万袋、期末在庫2,630万袋はいずれも予測値として確認できます。([apps.fas.usda.gov](https://apps.fas.usda.gov/psdonline/circulars/2026/07/coffee.pdf))"
    },
    {
      "fact_id": "COFFEE-009",
      "verdict": "VERIFIED",
      "verification_notes": "USDAはICO月次複合価格指数を用いて、コーヒー価格が直近7か月で25%下落し、追加供給が利用可能になったことと結び付けています。小売価格と混同していません。([apps.fas.usda.gov](https://apps.fas.usda.gov/psdonline/circulars/2026/07/coffee.pdf))"
    },
    {
      "fact_id": "COFFEE-010",
      "verdict": "VERIFIED",
      "verification_notes": "USDAブラジル現地報告は、ブラジル・ベトナムの悪天候による供給混乱、販売可能豆の限定、低在庫、強い国際需要を高価格の背景として列挙しています。複数要因としての記述も適切です。([apps.fas.usda.gov](https://apps.fas.usda.gov/newgainapi/api/Report/DownloadReportByFileName?fileName=Coffee+Annual_Brasilia_Brazil_BR2025-0013.pdf))"
    },
    {
      "fact_id": "COFFEE-011",
      "verdict": "VERIFIED",
      "verification_notes": "ICOの2026年1月報告は、1月6日頃の価格上昇の一部をブラジルレアルの対米ドル上昇を含む要因に結び付け、輸出国通貨上昇が国際価格に上昇圧力を与え得る仕組みを説明しています。「部分的」「可能性」とする要約は妥当です。([ico.org](https://www.ico.org/documents/cy2025-26/cmr-0126-e.pdf))"
    },
    {
      "fact_id": "COFFEE-012",
      "verdict": "VERIFIED",
      "verification_notes": "USDA報告は、2025年4月の10%関税、8月に追加された40%で計50%、11月14日の10%撤廃、11月20日のHS 0901対象40%撤廃を記載しています。可溶性コーヒーHS 2101.11.10は撤廃対象外という範囲の説明も確認できます。([apps.fas.usda.gov](https://apps.fas.usda.gov/newgainapi/api/Report/DownloadReportByFileName?fileName=Coffee+Semi-annual_Brasilia_Brazil_BR2025-0048.pdf&utm_source=openai))"
    },
    {
      "fact_id": "COFFEE-013",
      "verdict": "VERIFIED",
      "verification_notes": "Reutersは2025年11月21日10:17 GMT時点で、アラビカ先物が4.6%安の359.25米セント／ポンド、ロブスタ先物が5%安の4,400米ドル／トンで、各々一時6%超・8%下落したと報じています。これは先物の短期反応であり、因果を断定していません。([investing.com](https://www.investing.com/news/commodities-news/global-coffee-prices-plunge-after-trump-removes-tariffs-on-brazil-4372496))"
    },
    {
      "fact_id": "COFFEE-014",
      "verdict": "VERIFIED",
      "verification_notes": "Reuters記事は、専門家らの「少なくとも約9か月」という見積もり、ロースターの平均在庫約2～3か月分、焙煎・包装にさらに約2～3か月、四半期ごとの小売価格交渉を記載しています。全社共通の確定期間とはしていない点も適切です。([investing.com](https://www.investing.com/news/economic-indicators/us-coffee-drinkers-face-higher-prices-even-after-trumps-tariff-reset-4418417?ampMode=1))"
    },
    {
      "fact_id": "COFFEE-015",
      "verdict": "VERIFIED",
      "verification_notes": "BLSの2026年8月CPI表で「Coffee」の前年同月比+6.1%を確認できます。これはCPI項目の指数変化であり、カフェ一杯の価格そのものではありません。([bls.gov](https://www.bls.gov/news.release/cpi.htm))"
    },
    {
      "fact_id": "COFFEE-016",
      "verdict": "VERIFIED",
      "verification_notes": "APは政府統計に基づき、挽いたコーヒー1ポンドの平均価格が2025年9月に9.14ドル、8月の8.87ドルから3%上昇、前年同月比41%上昇と報じています。家庭用小売価格としての区別も妥当です。([apnews.com](https://apnews.com/article/3503a37a8fc95b7dc5a1f29747c81e27))"
    },
    {
      "fact_id": "COFFEE-017",
      "verdict": "VERIFIED",
      "verification_notes": "APはToastの決済データとして、2025年12月の米国レギュラー・ホットコーヒー中央値3.61ドル、コールドブリュー中央値5.55ドルを報じています。全国全店舗の公式平均ではなく、Toastデータとして扱う点も適切です。([apnews.com](https://apnews.com/article/1a809b2d3e650d5e92e2c0f5a5f4f85b))"
    },
    {
      "fact_id": "COFFEE-018",
      "verdict": "VERIFIED",
      "verification_notes": "APはMomentum Coffeeの4店舗でラテ等を約15%値上げし、運営者が豆の仕入れ費用も前年より15%高いと述べたことを報じています。カップ・スリーブや人件費も費用要因として挙げられており、個別事例としての限定も適切です。([apnews.com](https://apnews.com/article/3503a37a8fc95b7dc5a1f29747c81e27))"
    },
    {
      "fact_id": "COFFEE-019",
      "verdict": "VERIFIED",
      "verification_notes": "Reuters記事は、11月までの米国小売コーヒー価格の前年比18.8%上昇について、関税による部分はごく小さく、前年からの高い生豆相場・供給不足に主に関連すると専門家の見方を紹介しています。生豆が焙煎・粉砕コーヒーの製造費の少なくとも40%という説明も確認できます。関税寄与を統計的な確定推計ではなく関係者の評価としている点は適切です。([investing.com](https://www.investing.com/news/economic-indicators/us-coffee-drinkers-face-higher-prices-even-after-trumps-tariff-reset-4418417?ampMode=1))"
    }
  ]
}
